export const OPTIONS={fxType:['BYPASS','DELAY / MAGNET','GRID / LATTICE','NITRO / RESONANT','PHONE / TELECOM','PUNCH / IMPACT','SPRING / COIL','CWO / SIDEBAND'],fxRoute:['SOURCE → TAPE','MASTER → OUTPUT'],modType:['OFF','SINE','TRIANGLE','RANDOM / HOLD','VELOCITY','MIDI CC 1','ENVELOPE FOLLOW'],modTarget:['TONE','SHAPE','PITCH','DEVICE FX'],seqType:['PATTERN','ENDLESS','FINGER','TOMBOLA','SKETCH','ARPEGGIO'],seqDirection:['FORWARD','REVERSE','RANDOM'],playMode:['POLY','MONO','ONE SHOT'],sampleLoop:['ONE SHOT','LOOP'],sampleReverse:['FORWARD','REVERSE'],drumMode:['D-BOX / SYNTH','YOUR SAMPLE / 8 SLICES','FACTORY / STEREO KIT']};
export const GROUPS=[['sound','ENVELOPE / PLAY',['attack','decay','sustainLevel','release','playMode']],['sound','SAMPLE / REGIONS',['sampleStart','sampleEnd','sampleLoop','sampleReverse']],['sound','EFFECT / ROUTING',['fxType','fxRoute','fxA','fxB','fxC','fxMix']],['sound','MODULATION',['modType','modTarget','modRate','modDepth']],['drums','DRUM DEVICE',['drumMode','drumPitch','drumDecay','drumColour','drumShape']],['sequence','SEQUENCER DEVICE',['seqType','seqLength','seqDirection','seqGate','seqOctaves','gravity']],['mix-page','MASTER / EQ',['eqLow','eqMid','eqHigh','compressor']],['mix-page','EFFECT / ROUTING',['fxType','fxRoute','fxA','fxB','fxC','fxMix']]];
export function mountDevices(setParam,makeKnob){GROUPS.forEach(([page,title,ids],group)=>{const section=document.createElement('section');section.className='device-controls';const heading=document.createElement('h2');heading.textContent=title;section.append(heading);const grid=document.createElement('div');grid.className='device-grid';section.append(grid);ids.forEach((id,i)=>grid.append(makeKnob(id,i,`device-${group}`)));document.getElementById(page).append(section);});}
